def solve(rows):
  """Calculates the total cost of rows according to the given rules."""
  audit_positions = [(i, row) for i, row in enumerate(rows)]
  filtered_positions = [(i, row) for i, row in audit_positions if i % 4 != 2 or i == len(audit_positions) - 1]

  if not filtered_positions:
    return 0

  last_index = filtered_positions[-1][0]
  rotated_rows = []
  for i in range(len(filtered_positions)):
    if i == last_index: 
      rotated_rows.append(filtered_positions[i][1])
    else: 
      rotated_rows.append(filtered_positions[i][1])

  rotated_rows = rotated_rows[len(rotated_rows) % len(rotated_rows):] + rotated_rows[:len(rotated_rows) % len(rotated_rows)]

  total_cost = 0
  for row in rotated_rows:
    if row >= 0:
      if row <= 12:
        total_cost += row * 4
      else:
        total_cost += 12 * 4 + (row - 12) * 3
    if total_cost > 61:
      total_cost = 61

  return total_cost

